/**
 * Generate src/lib/api/apiSchema.generated.ts from the backend OpenAPI spec.
 *
 * Booking forms and quotations read enum options, maxLength limits, defaults
 * and required keys from the generated file instead of hardcoding them.
 *
 * Usage:
 *   node scripts/generate-api-schema.mjs                 # live /docs-json
 *   node scripts/generate-api-schema.mjs --file spec.json
 *   API_SCHEMA_URL=https://host/docs-json node scripts/generate-api-schema.mjs
 */
import fs from 'node:fs';
import path from 'node:path';

const DEFAULT_URL = 'https://kingfisherwings-backend.onrender.com/docs-json';
const OUT = path.join(process.cwd(), 'src/lib/api/apiSchema.generated.ts');

/** DTOs consumed by booking-form / quotation UIs. Extend when a new form needs one. */
const SCHEMAS = [
  // Staff mode booking forms — PUT /jobs/:id/{mode}/booking-form
  'UpsertSeaFclBookingFormDto',
  'UpsertSeaLclBookingFormDto',
  'UpsertLandBookingFormDto',
  'UpsertRoadFreightBookingFormDto',
  'UpsertCourierBookingFormDto',
  'UpsertCustomsClearanceBookingFormDto',
  'UpsertWarehouseBookingFormDto',
  'BookingFormPartyDto',
  'ContainerSizeLineDto',
  'WhStockLineInputDto',
  'CcCargoLineInputDto',
  // Air — /jobs/:id/air-booking-form, /air/compliance-form, portal shipments
  'UpsertAirBookingFormDto',
  'AirBookingFormPartyDto',
  'UpsertAirComplianceBookingFormDto',
  'AirCompliancePartyDto',
  'AirPalletLineDto',
  // NVOCC — /nvocc/bookings/:id/booking-form, portal bookings compliance-form
  'UpsertNvoccBookingFormDto',
  'NvoccBookingFormPartyDto',
  // Job detail DTOs — source of freight_terms / vehicle_type / bl_type enums
  'UpdateSeaFclJobDetailDto',
  'UpdateLandJobDetailDto',
  // Quotations
  'CreateQuotationDto',
  'UpdateQuotationDto',
  'CreateQuotationLineDto',
  'UpdateQuotationLineDto',
  'CargoPackageDto',
  'CreateOnlineQuoteDto',
  'PortalQuotationRequestDto',
  'PortalQuotationEstimateDto',
  'PortalCustomerLineDto',
  'PortalQuotationRejectDto',
  'GenerateQuotationPdfDto',
];

async function loadSpec() {
  const fileIdx = process.argv.indexOf('--file');
  if (fileIdx > -1) {
    return JSON.parse(fs.readFileSync(process.argv[fileIdx + 1], 'utf8'));
  }
  const url = process.env.API_SCHEMA_URL || DEFAULT_URL;
  // Render free tier can cold-start — allow a long wait.
  const res = await fetch(url, { signal: AbortSignal.timeout(180_000) });
  if (!res.ok) throw new Error(`GET ${url} → ${res.status}`);
  return res.json();
}

function unwrap(prop) {
  if (prop?.allOf?.length === 1) return { ...prop.allOf[0], ...prop, allOf: undefined };
  return prop ?? {};
}

function collect(spec) {
  const schemas = spec.components?.schemas ?? {};
  const enums = {};
  const maxLength = {};
  const defaults = {};
  const required = {};
  const keys = {};
  const missing = [];

  for (const name of SCHEMAS) {
    const schema = schemas[name];
    if (!schema) {
      missing.push(name);
      continue;
    }
    const e = {};
    const m = {};
    const d = {};
    const propKeys = Object.keys(schema.properties ?? {});
    for (const [key, raw] of Object.entries(schema.properties ?? {})) {
      const prop = unwrap(raw);
      const values = prop.enum ?? prop.items?.enum;
      if (Array.isArray(values)) e[key] = values;
      if (typeof prop.maxLength === 'number') m[key] = prop.maxLength;
      if (prop.default !== undefined) d[key] = prop.default;
    }
    enums[name] = e;
    maxLength[name] = m;
    defaults[name] = d;
    required[name] = schema.required ?? [];
    keys[name] = propKeys;
  }
  return { enums, maxLength, defaults, required, keys, missing };
}

function emit(name, doc, value) {
  return `/** ${doc} */\nexport const ${name} = ${JSON.stringify(value, null, 2)} as const;\n`;
}

const spec = await loadSpec();
const { enums, maxLength, defaults, required, keys, missing } = collect(spec);
if (missing.length) {
  console.error(`Schemas not found in spec: ${missing.join(', ')}`);
  process.exit(1);
}

const out = [
  '/* eslint-disable */',
  '// AUTO-GENERATED by scripts/generate-api-schema.mjs — DO NOT EDIT.',
  `// Source: OpenAPI "${spec.info?.title ?? ''}" v${spec.info?.version ?? '?'}. Regenerate: npm run gen:api-schema`,
  '',
  emit('API_ENUMS', 'Allowed values per DTO field (OpenAPI `enum`).', enums),
  emit('API_MAX_LENGTH', 'String length limits per DTO field (OpenAPI `maxLength`).', maxLength),
  emit('API_DEFAULTS', 'Server-side defaults per DTO field (OpenAPI `default`).', defaults),
  emit('API_REQUIRED', 'Required keys per DTO (OpenAPI `required`).', required),
  emit('API_SCHEMA_KEYS', 'Property keys per DTO (OpenAPI `properties`).', keys),
].join('\n');

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, out);
console.log(`Wrote ${path.relative(process.cwd(), OUT)} (${SCHEMAS.length} schemas).`);
